mapper.update:
update ${positionOperationTableName}
set warehouse_stock_detail_code = #{warehouseStockDetailCode}
where detail_code = #{detailCode}
and enterprise_code = #{enterpriseCode}

mapper.select:
SELECT COUNT(*) FROM ${positionOperationTableName} t
WHERE t.enterprise_code = #{enterpriseCode}
AND t.primary_key = #{positionOperationCode}

SELECT MIN(po.create_time) as first_outbound_time
FROM ${positionOperationTableName} po
WHERE po.detail_code IN (
    SELECT od.primary_key
    FROM ${outboundOrderDetailTableName} od
    INNER JOIN ${outboundOrderTableName} oo ON od.outbound_order = oo.primary_key
    WHERE oo.contract_number = #{contractNumber}
      AND oo.enterprise_code = #{enterpriseCode}
      AND od.delete_flag = false
)
  AND po.operation_type = true
  AND po.enterprise_code = #{enterpriseCode}
  AND po.delete_flag = false
